      expect(info.lat, closeTo(51.5, 0.01));
      expect(info.lng, closeTo(-0.1, 0.01));
      expect(info.isDefault, true);
    });

    test('parses lat/lng fields when no GeoPoint', () async {
      await fakeDb.collection('branches').doc('b_flat').set({
        'name': 'Flat Branch',
        'lat': 34.05,
        'lng': -118.24,
        'deliveryRadiusMiles': 5.0,
      });
      final doc = await fakeDb.collection('branches').doc('b_flat').get();
      final info = BranchInfo.fromDoc(doc);
      expect(info.lat, closeTo(34.05, 0.01));
      expect(info.lng, closeTo(-118.24, 0.01));
      expect(info.isDefault, false);
    });
  });

