  group('BranchService.nearestBranch', () {
    late FakeFirebaseFirestore fakeDbLocal;

    setUp(() async {
      fakeDbLocal = FakeFirebaseFirestore();
      await fakeDbLocal.collection('branches').doc('branch_a').set({
        'name': 'Branch A',
        'lat': 40.7128, // New York
        'lng': -74.0060,
        'deliveryRadiusMiles': 3.0,
      });
      await fakeDbLocal.collection('branches').doc('branch_b').set({
        'name': 'Branch B',
        'lat': 34.0522, // Los Angeles
        'lng': -118.2437,
        'deliveryRadiusMiles': 5.0,
      });
    });

    test(
      'returns nearest branch (New York user ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ Branch A)',
      () async {
        // Inject fake docs directly ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â bypasses GeoCollectionReference
        final service = BranchService(
          fakeDbLocal,
          logger: LoggerService(),
          fetchBranchesOverride: (_, __) async =>
              (await fakeDbLocal.collection('branches').get()).docs,
        );
        final branch = await service.nearestBranch(40.7851, -73.9683);
        expect(branch?.id, 'branch_a');
      },
    );

    test(
      'returns nearest branch (LA user ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ Branch B)',
      () async {
        final service = BranchService(
          fakeDbLocal,
          logger: LoggerService(),
          fetchBranchesOverride: (_, __) async =>
              (await fakeDbLocal.collection('branches').get()).docs,
        );
        final branch = await service.nearestBranch(34.0195, -118.4912);
        expect(branch?.id, 'branch_b');
      },
    );

    test('returns null if no branches exist', () async {
      final emptyDb = FakeFirebaseFirestore();
      final empty = BranchService(
        emptyDb,
        logger: LoggerService(),
